import{J as e,n as t,ot as n,q as r}from"./chunks/framework.8ZHN87l8.js";var i=JSON.parse(`{"title":"API reference","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"API reference"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/"}]],"pageClass":"api-index","editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/tools/docs/site/api/index.md"}},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md","lastUpdated":0}`),a={name:`api/index.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<h1 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to “API reference”">​</a></h1><p>The API reference for every package JSPrismarine publishes, generated from the TypeScript source and its doc comments. Pick a package for its classes, functions and types. <a href="/pr-preview/pr-3017/packages.html">Packages</a> says what each one is for and links its README and npm page.</p><p>Every package is published under the <code>@jsprismarine</code> scope.</p><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to “Server”">​</a></h2><p>The server itself, its console and the kernel that wires its modules.</p><ul><li><a href="./@jsprismarine/prismarine/">prismarine</a></li><li><a href="./@jsprismarine/server/">server</a></li><li><a href="./@jsprismarine/console/">console</a></li><li><a href="./@jsprismarine/console-protocol/">console-protocol</a></li><li><a href="./@jsprismarine/kernel/">kernel</a></li></ul><h2 id="network-and-protocol" tabindex="-1">Network and protocol <a class="header-anchor" href="#network-and-protocol" aria-label="Permalink to “Network and protocol”">​</a></h2><p>Packets, transports and sign-in, for a server or a client.</p><ul><li><a href="./@jsprismarine/protocol/">protocol</a></li><li><a href="./@jsprismarine/raknet/">raknet</a></li><li><a href="./@jsprismarine/nethernet/">nethernet</a></li><li><a href="./@jsprismarine/native-network/">native-network</a></li><li><a href="./@jsprismarine/auth/">auth</a></li><li><a href="./@jsprismarine/client/">client</a></li><li><a href="./@jsprismarine/binaryutils/">binaryutils</a></li></ul><h2 id="world" tabindex="-1">World <a class="header-anchor" href="#world" aria-label="Permalink to “World”">​</a></h2><p>Terrain, decoration, light, storage and the systems that tick a world.</p><ul><li><a href="./@jsprismarine/worldgen/">worldgen</a></li><li><a href="./@jsprismarine/chunkgen/">chunkgen</a></li><li><a href="./@jsprismarine/features/">features</a></li><li><a href="./@jsprismarine/structures/">structures</a></li><li><a href="./@jsprismarine/lighting/">lighting</a></li><li><a href="./@jsprismarine/leveldb/">leveldb</a></li><li><a href="./@jsprismarine/engine-systems/">engine-systems</a></li><li><a href="./@jsprismarine/spawning/">spawning</a></li></ul><h2 id="gameplay" tabindex="-1">Gameplay <a class="header-anchor" href="#gameplay" aria-label="Permalink to “Gameplay”">​</a></h2><p>Blocks, items, entities, commands and the rules that make them vanilla.</p><ul><li><a href="./@jsprismarine/content/">content</a></li><li><a href="./@jsprismarine/blocks/">blocks</a></li><li><a href="./@jsprismarine/block-behaviors/">block-behaviors</a></li><li><a href="./@jsprismarine/items/">items</a></li><li><a href="./@jsprismarine/item-behaviors/">item-behaviors</a></li><li><a href="./@jsprismarine/entities/">entities</a></li><li><a href="./@jsprismarine/entity-brains/">entity-brains</a></li><li><a href="./@jsprismarine/entity-goals/">entity-goals</a></li><li><a href="./@jsprismarine/recipes/">recipes</a></li><li><a href="./@jsprismarine/loot/">loot</a></li><li><a href="./@jsprismarine/enchantments/">enchantments</a></li><li><a href="./@jsprismarine/trading/">trading</a></li><li><a href="./@jsprismarine/advancements/">advancements</a></li><li><a href="./@jsprismarine/commands/">commands</a></li><li><a href="./@jsprismarine/brigadier/">brigadier</a></li><li><a href="./@jsprismarine/mcfunction/">mcfunction</a></li><li><a href="./@jsprismarine/predicates/">predicates</a></li></ul><h2 id="data-and-formats" tabindex="-1">Data and formats <a class="header-anchor" href="#data-and-formats" aria-label="Permalink to “Data and formats”">​</a></h2><p>Game data, identifiers, packs, Molang and the file formats they use.</p><ul><li><a href="./@jsprismarine/bedrock-data/">bedrock-data</a></li><li><a href="./@jsprismarine/minecraft/">minecraft</a></li><li><a href="./@jsprismarine/mapping/">mapping</a></li><li><a href="./@jsprismarine/nbt/">nbt</a></li><li><a href="./@jsprismarine/molang/">molang</a></li><li><a href="./@jsprismarine/packs/">packs</a></li><li><a href="./@jsprismarine/color-parser/">color-parser</a></li></ul><h2 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to “Utilities”">​</a></h2><p>Errors, logging and math shared by the other packages.</p><ul><li><a href="./@jsprismarine/errors/">errors</a></li><li><a href="./@jsprismarine/logger/">logger</a></li><li><a href="./@jsprismarine/math/">math</a></li></ul>`,21)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};